CREATE OR REPLACE FUNCTION public.expire_group_campaigns() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE expired_row record; BEGIN FOR expired_row IN SELECT id FROM public.group_buying_campaigns WHERE lifecycle='active' AND closes_at<=now() ORDER BY id FOR UPDATE SKIP LOCKED LOOP PERFORM public.release_group_campaign(expired_row.id,'expired'); END LOOP; UPDATE public.group_buying_campaigns campaign SET lifecycle='completed' WHERE campaign.lifecycle='target_reached' AND campaign.closes_at<=now() AND NOT EXISTS(SELECT 1 FROM public.orders o WHERE o.campaign_id=campaign.id AND o.status NOT IN ('delivered','completed','rejected','cancelled')); END $$;